Reviewing a teammate's Go change for our invoices list endpoint and I want a tougher read than the usual. It adds cursor pagination. We already have `pkg/cursor` with `Encode(key map[string]string) string` and `Decode(s string) (map[string]string, error)` that signs and checks the token, but I'm not sure this PR uses it.

```diff
+++ b/api/invoices/list.go
+func (h *Handler) List(w http.ResponseWriter, r *http.Request) {
+	tok := r.URL.Query().Get("page_token")
+	var start map[string]types.AttributeValue
+	if tok != "" {
+		raw, _ := base64.StdEncoding.DecodeString(tok)
+		var m map[string]string
+		json.Unmarshal(raw, &m)
+		start = map[string]types.AttributeValue{
+			"pk": &types.AttributeValueMemberS{Value: m["pk"]},
+			"sk": &types.AttributeValueMemberS{Value: m["sk"]},
+		}
+	}
+	out, err := h.db.Query(r.Context(), &dynamodb.QueryInput{
+		TableName:         aws.String("invoices"),
+		KeyConditionExpression: aws.String("pk = :p"),
+		ExpressionAttributeValues: map[string]types.AttributeValue{
+			":p": &types.AttributeValueMemberS{Value: "ACCT#" + h.accountID(r)},
+		},
+		ExclusiveStartKey: start,
+	})
+	if err != nil {
+		http.Error(w, err.Error(), 500)
+		return
+	}
+	json.NewEncoder(w).Encode(out.Items)
+}
```

