I'm the maker on this one and need a rough list of everything wrong before the checker pass, noise is fine. It's a brand new TypeScript handler that marks a bunch of shipments as delivered and returns errors to our partner API. The route entry in serverless.yml and the partner authorizer config aren't part of this PR, I planned to do those in a follow-up.

```diff
+++ b/src/shipments/markDelivered.ts
+export async function markDelivered(req: Request, res: Response) {
+  const ids: string[] = req.body.shipmentIds;
+  const done: string[] = [];
+  try {
+    for (const id of ids) {
+      await ddb.send(new UpdateItemCommand({
+        TableName: "shipments",
+        Key: { id: { S: id } },
+        UpdateExpression: "SET #st = :d, deliveredAt = :t",
+        ExpressionAttributeNames: { "#st": "status" },
+        ExpressionAttributeValues: { ":d": { S: "DELIVERED" }, ":t": { S: new Date().toISOString() } },
+      }));
+      done.push(id);
+    }
+    res.json({ updated: done });
+  } catch (err: any) {
+    res.status(500).json({ message: err.message, stack: err.stack, table: "shipments", done });
+  }
+}
```

